UPDATE mobi_points_account
SET base_points = base_points - #{deductBase},
    bonus_points = bonus_points - #{deductBonus},
    total_used_points = total_used_points + #{total},
    update_time = NOW()
WHERE user_id = #{userId}
  AND shop_id = #{shopId}
  AND base_points + bonus_points >= #{total}
